mapper.select:
WITH updated_wallet AS (
    UPDATE wallets
    SET cash_balance = cash_balance - #{amount}
    WHERE wallet_id = #{walletId}
      AND (cash_balance - frozen_amount) >= #{amount}
        RETURNING cash_balance
)
INSERT INTO transaction_hists (
    transaction_id, trade_id, order_id, wallet_id,
    transaction_type, asset_type, direction, amount,
    balance_after, remaining_price, remaining_volume,
    created_at, fee, hash_value
)
SELECT
    #{transactionId}, #{subscriptionId}, NULL, #{walletId},
    'SUBSCRIPTION', 'CASH', 'OUT', #{amount},
    uw.cash_balance, 0, 0,
    NOW(), 0, #{hashValue}
FROM updated_wallet uw
    RETURNING transaction_id
